sys_variable_value.value:
(function execute(inputs, outputs) {
    var helper = new x_1815796_itsmgr_0.AiBotHelper();
    var result = helper.getFile(inputs.file_id);
    
    outputs.success = result.success;
    outputs.details = result.details;
    outputs.error_message = result.error_message;

    // Parsing the content out of the details object
    if (result.success && result.details) {
        try {
            // Check if details is already an object or needs parsing
            var detailsObj = (typeof result.details === 'string') ? JSON.parse(result.details) : result.details;
            
            // Navigate to the 'content' field: details -> data -> content
            if (detailsObj.data && detailsObj.data.content) {
                outputs.file_content = detailsObj.data.content;
            } else {
                outputs.file_content = ""; 
            }
        } catch (e) {
            outputs.error_message = "Failed to parse file content: " + e.message;
            outputs.file_content = "";
        }
    }
})(inputs, outputs);

